            continue
        groups[shape_key(cells)].append((color,cells))
    repeated = [items for items in groups.values() if len(items) >= 2]
    if not repeated:
        return out
    # Recolor the most distant copy from the L key in a repeated-shape set.
    # Prefer the repeated shape group whose nearest member is closest to the key.
    repeated.sort(key=lambda items: min(abs(sum(r for r,c in cs)/len(cs)-mr)+abs(sum(c for r,c in cs)/len(cs)-mc) for _,cs in items))
